def factorial(num):
    """ Helper function to calculate factorial of a number """
    if num == 0 or num == 1:
        return 1
    else:
        return num * factorial(num - 1)

def sum(range_start, range_end):
    """ Helper function to calculate the sum of numbers from range_start to range_end """
